// Long-running hacking script
/** @param {NS} ns */
export async function main(ns) {
    const servers = new Set();
    let timeoutId;

    async function updateServers() {
        for (const server of ns.getServerNames()) {
            servers.add(server);
        }
        setTimeout(updateServers, 1000);
    }

    async function hackLoop() {
        while (true) {
            const target = Array.from(servers).reduce((a, b) => {
                if (!ns.hasRootAccess(b)) return a;
                const money = ns.getServerMoneyAvailable(b);
                const security = ns.getServerSecurityLevel(b);
                return money * security > a.money * a.security ? { name: b, money, security } : a;
            }, { name: '', money: 0, security: Infinity });

            if (target.name) {
                while (ns.getWeakenTime(target.name) < ns.getHackTime(target.name)) {
                    await ns.weaken(target.name);
                }
                await ns.hack(target.name);
                ns.grow(target.name);
            }

            setTimeout(hackLoop, 1000);
        }
    }

    updateServers();
    hackLoop();
}

